class SavedVersesScreen extends StatefulWidget {
  const SavedVersesScreen({super.key});

  @override
  State<SavedVersesScreen> createState() => _SavedVersesScreenState();
}

class _SavedVersesScreenState extends State<SavedVersesScreen> {
  List<Map<String, dynamic>> _savedVerses = [];

  @override
  void initState() {
    super.initState();
    _loadSavedVerses();
  }

  Future<void> _loadSavedVerses() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final savedVersesJson = prefs.getStringList('saved_verses') ?? [];

      setState(() {
        _savedVerses = savedVersesJson.map((json) {
          return jsonDecode(json) as Map<String, dynamic>;
        }).toList();
        _savedVerses.sort((a, b) {
          final dateA = DateTime.parse(a['date'] as String);
          final dateB = DateTime.parse(b['date'] as String);
          return dateB.compareTo(dateA);
        });
      });
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).hideCurrentSnackBar();
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text('Սխալ: $e'),
            duration: const Duration(seconds: 1),
          ),
        );
      }
    }
  }

  Future<void> _deleteVerse(Map<String, dynamic> verseToDelete) async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final savedVersesJson = prefs.getStringList('saved_verses') ?? [];

      final verseJson = jsonEncode(verseToDelete);
      savedVersesJson.remove(verseJson);
      await prefs.setStringList('saved_verses', savedVersesJson);

      await _loadSavedVerses();

      if (mounted) {
        ScaffoldMessenger.of(context).hideCurrentSnackBar();
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text('Հատվածը ջնջված է'),
            duration: Duration(seconds: 1),
          ),
        );
      }
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).hideCurrentSnackBar();
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text('Սխալ: $e'),
            duration: const Duration(seconds: 1),
          ),
        );
      }
    }
  }

  Future<void> _copyVerse(
    String bookName,
    int chapterNumber,
    int verseNumber,
    String verseText,
  ) async {
    await VerseHelper.copyVerse(
      context,
      bookName,
      chapterNumber,
      verseNumber,
      verseText,
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('Պահված հատվածներ'),
        leading: IconButton(
          icon: const Icon(Icons.arrow_back, color: Colors.white),
          onPressed: () => Navigator.pop(context),
        ),
      ),
      body: _savedVerses.isEmpty
          ? Center(
              child: Column(
                mainAxisAlignment: MainAxisAlignment.center,
                children: [
                  Icon(
                    Icons.bookmark_border,
                    size: 64,
                    color: Colors.grey[400],
                  ),
                  const SizedBox(height: 16),
                  Text(
                    'Պահված հատվածներ չկան',
                    style: Theme.of(
                      context,
                    ).textTheme.titleLarge?.copyWith(color: Colors.grey[600]),
                  ),
                  const SizedBox(height: 8),
                  Text(
                    'Սեղմեք համարի վրա՝ պահելու համար',
                    style: Theme.of(
                      context,
                    ).textTheme.bodyMedium?.copyWith(color: Colors.grey[500]),
                    textAlign: TextAlign.center,
                  ),
                ],
              ),
            )
          : // SavedVersesScreen-ի build մեթոդում փոխարինել ListView.builder-ը
          RefreshIndicator(
              onRefresh: _loadSavedVerses,
              child: ListView.builder(
                padding: const EdgeInsets.all(16),
                itemCount: _savedVerses.length,
                itemBuilder: (context, index) {
                  final verse = _savedVerses[index];
                  final bookName = verse['book'] as String;
                  final chapterNumber = verse['chapter'] as int;
                  final verseNumber = verse['verse'] as int;
                  final verseText = verse['text'] as String;
                  final dateStr = verse['date'] as String;
                  final range = verse['range'] as String?;
                  final verseCount = verse['verseCount'] as int? ?? 1;
                  final date = DateTime.parse(dateStr);

                  // Ստեղծել ցուցադրման տեքստը
                  String displayText;
                  if (range != null) {
                    displayText = '$bookName $chapterNumber:$range';
                  } else {
                    displayText = '$bookName $chapterNumber:$verseNumber';
                  }

                  return Card(
                    margin: const EdgeInsets.only(bottom: 12),
                    child: InkWell(
                      onTap: () {
                        final text = bibleText[bookName]?[chapterNumber] ??
                            'Տեքստը դեռ չի ավելացվել';
                        final List<int> selectedVerses;
                        if (range != null && range.contains('-')) {
                          final parts = range.split('-');
                          final start = int.parse(parts[0]);
                          final end = int.parse(parts[1]);
                          selectedVerses = [
                            for (int n = start; n <= end; n++) n,
                          ];
                        } else {
                          selectedVerses = [verseNumber];
                        }

                        Navigator.push(
                          context,
                          MaterialPageRoute(
                            builder: (_) => ChapterTextScreen(
                              bookName: bookName,
                              chapterNumber: chapterNumber,
                              text: text,
                              targetVerse: selectedVerses.first,
                              initialSelectedVerses: selectedVerses,
                            ),
                          ),
                        );
                      },
                      child: Padding(
                        padding: const EdgeInsets.all(16),
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Row(
                              mainAxisAlignment: MainAxisAlignment.spaceBetween,
                              children: [
                                Expanded(
                                  child: Text(
                                    displayText,
                                    style: Theme.of(context)
                                        .textTheme
                                        .titleMedium
                                        ?.copyWith(
                                          fontWeight: FontWeight.bold,
                                          color: Colors.grey,
                                        ),
                                  ),
                                ),
                                if (verseCount > 1)
                                  Container(
                                    padding: const EdgeInsets.symmetric(
                                      horizontal: 8,
                                      vertical: 4,
                                    ),
                                    decoration: BoxDecoration(
                                      color: Colors.blue.withOpacity(0.1),
                                      borderRadius: BorderRadius.circular(12),
                                    ),
                                    child: Text(
                                      '$verseCount հատված',
                                      style: Theme.of(context)
                                          .textTheme
                                          .bodySmall
                                          ?.copyWith(
                                            color: Colors.blue,
                                            fontWeight: FontWeight.w500,
                                          ),
                                    ),
                                  ),
                                IconButton(
                                  icon: const Icon(Icons.delete_outline),
                                  onPressed: () => _deleteVerse(verse),
                                  tooltip: 'Ջնջել',
                                ),
                              ],
                            ),
                            const SizedBox(height: 8),
                            Text(
                              verseText,
                              style: Theme.of(context).textTheme.bodyMedium,
                              maxLines: 5,
                              overflow: TextOverflow.ellipsis,
                            ),
                            const SizedBox(height: 8),
                            Row(
                              mainAxisAlignment: MainAxisAlignment.spaceBetween,
                              children: [
                                Text(
                                  '${date.day}.${date.month}.${date.year}',
                                  style: Theme.of(context)
                                      .textTheme
                                      .bodySmall
                                      ?.copyWith(color: Colors.blueGrey[600]),
                                ),
                                IconButton(
                                  icon: const Icon(
                                    Icons.content_copy,
                                    size: 20,
                                  ),
                                  onPressed: () => _copyVerse(
                                    bookName,
                                    chapterNumber,
                                    verseNumber,
                                    verseText,
                                  ),
                                  tooltip: 'Պատճենել',
                                ),
                              ],
                            ),
                          ],
                        ),
                      ),
                    ),
                  );
                },
              ),
            ),
    );
  }
}

class BooksScreen extends StatelessWidget {
  final String title;
  final List<String> firstColumn;
  final List<String> secondColumn;

  const BooksScreen({
    super.key,
    required this.title,
    required this.firstColumn,
    required this.secondColumn,
  });

  @override
  Widget build(BuildContext context) {
    final List<String> combined = <String>[];
    final int maxLen = firstColumn.length > secondColumn.length
        ? firstColumn.length
        : secondColumn.length;
    for (int i = 0; i < maxLen; i++) {
      if (i < firstColumn.length) combined.add(firstColumn[i]);
      if (i < secondColumn.length) combined.add(secondColumn[i]);
    }

    return Scaffold(
      appBar: AppBar(
        leading: IconButton(
          icon: const Icon(Icons.arrow_back, color: Colors.white),
          onPressed: () => Navigator.pop(context),
        ),
        title: Container(
          margin: const EdgeInsets.symmetric(horizontal: 16),
          height: 40,
          child: TextField(
            decoration: InputDecoration(
              hintText: 'Փնտրել',
              hintStyle: const TextStyle(
                fontSize: 14,
                color: Colors.black,
              ),
              border: OutlineInputBorder(
                borderRadius: BorderRadius.circular(20),
                borderSide: BorderSide.none,
              ),
              filled: true,
              // Одинаковый цвет фона поиска и в светлой, и в тёмной теме
              fillColor: const Color.fromARGB(255, 188, 201, 202),
              contentPadding: const EdgeInsets.symmetric(
                horizontal: 16,
                vertical: 0,
              ),
              prefixIcon: Icon(
                Icons.search,
                // Иконка поиска тоже одинакова в обеих темах
                color: const Color.fromARGB(255, 0, 0, 0),
                size: 20,
              ),
            ),
            onTap: () {
              Navigator.push(
                context,
                MaterialPageRoute(builder: (_) => const SearchScreen()),
              );
            },
          ),
        ),
        actions: const [SizedBox(width: 8)],
      ),
      body: Column(
        children: [
          Container(
            width: double.infinity,
            padding: const EdgeInsets.all(16.0),
            child: Text(
              title,
              style: TextStyle(
                fontSize: 24,
                fontWeight: FontWeight.bold,
                color: Theme.of(context).brightness == Brightness.dark
                    ? Colors.white
                    : Colors.black,
              ),
              textAlign: TextAlign.center,
            ),
          ),
          Expanded(
            child: LayoutBuilder(
              builder: (context, constraints) {
                final isNarrow = constraints.maxWidth < 360;
                final padding = isNarrow ? 12.0 : 20.0;
                final spacing = isNarrow ? 8.0 : 12.0;
                final innerWidth = constraints.maxWidth - padding * 2;
                final cellWidth = (innerWidth - spacing) / 2;
                final cellHeight = math.max(48.0, math.min(56.0, cellWidth / 3.2));
                return Padding(
                  padding: EdgeInsets.all(padding),
                  child: GridView.builder(
                    itemCount: combined.length,
                    gridDelegate: SliverGridDelegateWithFixedCrossAxisCount(
                      crossAxisCount: 2,
                      mainAxisSpacing: spacing,
                      crossAxisSpacing: spacing,
                      childAspectRatio: cellWidth / cellHeight,
                    ),
                    itemBuilder: (context, index) {
                      final book = combined[index];
                      return ElevatedButton(
                        onPressed: () {
                          final chapters = chapterCounts[book] ?? 1;
                          Navigator.push(
                            context,
                            MaterialPageRoute(
                              builder: (_) => ChaptersScreen(
                                bookName: book,
                                chapters: chapters,
                              ),
                            ),
                          );
                        },
                        style: ElevatedButton.styleFrom(
                          padding: const EdgeInsets.symmetric(horizontal: 10),
                          minimumSize: Size.zero,
                          tapTargetSize: MaterialTapTargetSize.shrinkWrap,
                          visualDensity: VisualDensity.compact,
                        ),
                        child: FittedBox(
                          fit: BoxFit.scaleDown,
                          child: Text(
                            book,
                            maxLines: 1,
                            textAlign: TextAlign.center,
                          ),
                        ),
                      );
                    },
                  ),
                );
              },
            ),
          ),
        ],
      ),
    );
  }
}

class ChaptersScreen extends StatefulWidget {
  final String bookName;
  final int chapters;

  const ChaptersScreen({
    super.key,
    required this.bookName,
    required this.chapters,
  });

  @override
  State<ChaptersScreen> createState() => _ChaptersScreenState();
}

class _ChaptersScreenState extends State<ChaptersScreen> {
  int _tabIndex = 0;
  int? _selectedChapter;

  List<int> _verseNumbersFor(int chapterNumber) {
    final text = bibleText[widget.bookName]?[chapterNumber] ?? '';
    final verses = VerseHelper.parseVerses(text);
    if (verses.isEmpty) return const [1];
    final numbers = verses.keys.toList()..sort();
    return numbers;
  }

  void _openChapter(int chapterNumber, {int? targetVerse}) {
    final text = bibleText[widget.bookName]?[chapterNumber] ??
        'Տեքստը դեռ չի ավելացվել';
    Navigator.push(
      context,
      MaterialPageRoute(
        builder: (_) => ChapterTextScreen(
          bookName: widget.bookName,
          chapterNumber: chapterNumber,
          text: text,
          targetVerse: targetVerse,
        ),
      ),
    );
  }

  Widget _numberButton({
    required String label,
    required bool selected,
    required VoidCallback onPressed,
  }) {
    return LayoutBuilder(
      builder: (context, constraints) {
        final side = math.min(constraints.maxWidth, constraints.maxHeight);
        return Center(
          child: SizedBox(
            width: side,
            height: side,
            child: Material(
              color: selected ? Colors.white : Colors.grey[800],
              shape: const CircleBorder(),
              clipBehavior: Clip.antiAlias,
              child: InkWell(
                customBorder: const CircleBorder(),
                onTap: onPressed,
                child: Padding(
                  padding: const EdgeInsets.all(6),
                  child: FittedBox(
                    fit: BoxFit.scaleDown,
                    child: Text(
                      label,
                      textAlign: TextAlign.center,
                      style: TextStyle(
                        fontSize: 16,
                        fontWeight: FontWeight.w500,
                        height: 1,
                        color: selected ? Colors.black : Colors.white,
                      ),
                    ),
                  ),
                ),
              ),
            ),
          ),
        );
      },
    );
  }

  Widget _tabChip(String title, int index, {bool enabled = true}) {
    final selected = _tabIndex == index;
    return Expanded(
      child: Padding(
        padding: const EdgeInsets.symmetric(horizontal: 6),
        child: ElevatedButton(
          onPressed: enabled
              ? () => setState(() => _tabIndex = index)
              : null,
          style: ElevatedButton.styleFrom(
            backgroundColor: selected ? Colors.white : Colors.grey[800],
            foregroundColor: selected ? Colors.black : Colors.white,
            disabledBackgroundColor: Colors.grey[700],
            disabledForegroundColor: Colors.white54,
          ),
          child: FittedBox(
            fit: BoxFit.scaleDown,
            child: Text(title),
          ),
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final verseNumbers = _selectedChapter == null
        ? const <int>[]
        : _verseNumbersFor(_selectedChapter!);

    return Scaffold(
      appBar: AppBar(
        title: FittedBox(
          fit: BoxFit.scaleDown,
          child: Text(
            _selectedChapter == null
                ? widget.bookName
                : '${widget.bookName} $_selectedChapter',
            maxLines: 1,
          ),
        ),
        leading: IconButton(
          icon: const Icon(Icons.arrow_back, color: Colors.white),
          onPressed: () => Navigator.pop(context),
        ),
      ),
      body: Column(
        children: [
          Padding(
            padding: const EdgeInsets.fromLTRB(16, 16, 16, 8),
            child: Row(
              children: [
                _tabChip('Գլուխ', 0),
                _tabChip('Համար', 1, enabled: _selectedChapter != null),
              ],
            ),
          ),
          Expanded(
            child: LayoutBuilder(
              builder: (context, constraints) {
                final isNarrow = constraints.maxWidth < 360;
                final padding = isNarrow ? 12.0 : 20.0;
                final spacing = isNarrow ? 8.0 : 12.0;
                final grid = _tabIndex == 0
                    ? GridView.builder(
                        itemCount: widget.chapters,
                        gridDelegate: SliverGridDelegateWithFixedCrossAxisCount(
                          crossAxisCount: 5,
                          mainAxisSpacing: spacing,
                          crossAxisSpacing: spacing,
                          childAspectRatio: 1,
                        ),
                        itemBuilder: (context, index) {
                          final chapterNumber = index + 1;
                          final selected = _selectedChapter == chapterNumber;
                          return _numberButton(
                            label: '$chapterNumber',
                            selected: selected,
                            onPressed: () {
                              setState(() {
                                _selectedChapter = chapterNumber;
                                _tabIndex = 1;
                              });
                            },
                          );
                        },
                      )
                    : GridView.builder(
                        itemCount: verseNumbers.length,
                        gridDelegate: SliverGridDelegateWithFixedCrossAxisCount(
                          crossAxisCount: 5,
                          mainAxisSpacing: spacing,
                          crossAxisSpacing: spacing,
                          childAspectRatio: 1,
                        ),
                        itemBuilder: (context, index) {
                          final verseNumber = verseNumbers[index];
                          return _numberButton(
                            label: '$verseNumber',
                            selected: false,
                            onPressed: () => _openChapter(
                              _selectedChapter!,
                              targetVerse: verseNumber,
                            ),
                          );
                        },
                      );
                return Padding(
                  padding: EdgeInsets.all(padding),
                  child: grid,
                );
              },
            ),
          ),
        ],
      ),
    );
  }
}

class VerseHelper {
  static Map<int, String> parseVerses(String text) {
    final Map<int, String> verses = {};

    final versePattern = RegExp(r'(\d+)[*]?\s*');
    final allMatches = versePattern.allMatches(text).toList();

    if (allMatches.isEmpty) return verses;

    for (int i = 0; i < allMatches.length; i++) {
      final match = allMatches[i];
      final verseNum = int.tryParse(match.group(1) ?? '');

      if (verseNum == null) continue;

      int verseEnd = text.length;
      if (i < allMatches.length - 1) {
        verseEnd = allMatches[i + 1].start;
      }

      var verseText = text.substring(match.end, verseEnd).trim();
      verseText = verseText.replaceAll(RegExp(r'\s+'), ' ').trim();

      if (verseText.isNotEmpty) {
        verses[verseNum] = verseText;
      }
    }

    return verses;
  }

  static Future<void> scrollToVerse({
    required ScrollController controller,
    required GlobalKey? Function() keyOf,
    required bool Function() isMounted,
    int attempt = 0,
    VoidCallback? onDone,
  }) async {
    if (!isMounted() || attempt > 40) {
      if (isMounted()) onDone?.call();
      return;
    }

    await Future<void>.delayed(
      Duration(milliseconds: attempt == 0 ? 50 : 80),
    );
    if (!isMounted()) return;

    final key = keyOf();
    final ctx = key?.currentContext;
    final renderObject = ctx?.findRenderObject();
    if (ctx == null || renderObject == null || !renderObject.attached) {
      await scrollToVerse(
        controller: controller,
        keyOf: keyOf,
        isMounted: isMounted,
        attempt: attempt + 1,
        onDone: onDone,
      );
      return;
    }

    try {
      if (controller.hasClients) {
        final viewport = RenderAbstractViewport.of(renderObject);
        final revealed = viewport.getOffsetToReveal(renderObject, 0.18);
        final position = controller.position;
        final target = revealed.offset.clamp(
          position.minScrollExtent,
          position.maxScrollExtent,
        );
        await controller.animateTo(
          target,
          duration: const Duration(milliseconds: 300),
          curve: Curves.easeInOut,
        );
        if (isMounted()) onDone?.call();
        return;
      }
    } catch (_) {}

    if (!isMounted()) return;
    await Scrollable.ensureVisible(
      ctx,
      duration: const Duration(milliseconds: 300),
      curve: Curves.easeInOut,
      alignment: 0.18,
    );
    if (isMounted()) onDone?.call();
  }

  static String? getVerseText(String text, int verseNumber) {
    final verses = parseVerses(text);
    return verses[verseNumber];
  }

  static Future<double> loadReaderFontSize() async {
    final prefs = await SharedPreferences.getInstance();
    return prefs.getDouble(_readerFontSizePrefsKey) ?? _defaultReaderFontSize;
  }

  static Future<void> saveReaderFontSize(double size) async {
    final prefs = await SharedPreferences.getInstance();
    await prefs.setDouble(_readerFontSizePrefsKey, size);
  }

