  static Widget buildClickableVerseText(
    BuildContext context,
    String text,
    String bookName,
    int chapterNumber, {
    String? selectedWordKey,
    Function(String, int, int, String, String?)? onWordClick,
    Map<int, GlobalKey>? verseKeys,
    bool enableMultiSelect = false,
    Set<int>? multiSelectedVerses,
    void Function(int verseNumber, String verseText)? onVerseSelectToggle,
    Function(String, int, int, String, String?)? onVerseAction,
    double readerFontSize = _defaultReaderFontSize,
    int? targetVerse,
  }) {
    final List<InlineSpan> children = [];
    final textTheme = Theme.of(context).textTheme.bodyMedium;
    final isDark = Theme.of(context).brightness == Brightness.dark;
    final double bodySize = readerFontSize;
    final double subtitleSize =
        (readerFontSize * 0.8).clamp(12.0, 22.0).toDouble();
    final double headingSize =
        (readerFontSize * 1.4).clamp(22.0, 40.0).toDouble();
    final baseStyle = textTheme?.copyWith(
          fontSize: bodySize,
          height: 1.6,
          color: isDark ? Colors.white : Colors.black,
        ) ??
        TextStyle(
          fontSize: bodySize,
          height: 1.6,
          color: isDark ? Colors.white : Colors.black,
        );

    // Заголовки акростиха 118 (119) псалма
    const psalm119Headings = [
      'ԱԼԷՖ',
      'ԲԷԹ',
      'ԳԻՄԷԼ',
      'ԴԱԼԷԹ',
      'ՀԷ',
      'ՎԱՎ',
      'ԶԱՅԻՆ',
      'ԽԷԹ',
      'ԹԵԹ',
      'ՅՈԴ',
      'ՔԱՖ',
      'ԼԱՄԷԴ',
      'ՄԷՄ',
      'ՆՈՒՆ',
      'ՍԱՄԷԽ',
      'ԱՅԻՆ',
      'ՓԷ',
      'ՑԱԴԷ',
      'ՔՈՖ',
      'ՐԷՇ',
      'ՇԻՆ',
      'ԹԱՎ',
    ];

    final versePattern = RegExp(r'(\d+)[*]?\s*');
    final firstVerseMatch = versePattern.firstMatch(text);

    String? subtitleText;
    String textToProcess = text;

    if (firstVerseMatch != null && firstVerseMatch.start > 0) {
      subtitleText = text.substring(0, firstVerseMatch.start).trim();

      if (subtitleText.isNotEmpty && !subtitleText.contains(RegExp(r'^\d+'))) {
        // Особая обработка подзаголовка в 119-м псалме:
        // строка с «ԱԼԷՖ» (и другими заголовками) должна быть отдельным
        // крупным текстом по центру, а остальное — как обычный подзаголовок.
        if (bookName == 'Սաղմոս' && chapterNumber == 119) {
          final lines = subtitleText.split('\n');

          for (final line in lines) {
            final trimmed = line.trim();
            if (trimmed.isEmpty) continue;

            if (psalm119Headings.contains(trimmed)) {
              children.add(
                WidgetSpan(
                  child: Padding(
                    padding: const EdgeInsets.only(top: 16.0, bottom: 8.0),
                    child: Text(
                      trimmed,
                      textAlign: TextAlign.center,
                      style: baseStyle.copyWith(
                        fontSize: headingSize,
                        fontWeight: FontWeight.bold,
                        color: isDark ? Colors.white : Colors.black,
                      ),
                    ),
                  ),
                ),
              );
            } else {
              children.add(
                TextSpan(
                  text: '$trimmed\n',
                  style: baseStyle.copyWith(
                    fontWeight: FontWeight.w500,
                    fontStyle: FontStyle.italic,
                    color: isDark ? Colors.blueGrey[300] : Colors.blueGrey[700],
                    fontSize: subtitleSize,
                  ),
                ),
              );
            }
          }
        } else {
          children.add(
            TextSpan(
              text: '$subtitleText\n',
              style: baseStyle.copyWith(
                fontWeight: FontWeight.w500,
                fontStyle: FontStyle.italic,
                color: isDark ? Colors.blueGrey[300] : Colors.blueGrey[700],
                fontSize: subtitleSize,
              ),
            ),
          );
        }

        textToProcess = text.substring(firstVerseMatch.start);
      }
    }

    final processedMatches = versePattern.allMatches(textToProcess).toList();

    if (processedMatches.isEmpty) {
      return SelectableText.rich(
        TextSpan(text: textToProcess, style: baseStyle),
      );
    }

    final List<Map<String, dynamic>> verses = [];
    int lastEnd = 0;

    for (int i = 0; i < processedMatches.length; i++) {
      final match = processedMatches[i];

      final verseNum = match.group(1)!;
      final verseNumber = int.tryParse(verseNum);

      int verseEnd = textToProcess.length;
      if (i < processedMatches.length - 1) {
        final nextMatch = processedMatches[i + 1];
        verseEnd = nextMatch.start;
      }

      final verseText = textToProcess.substring(match.end, verseEnd).trim();

      if (match.start > lastEnd) {
        final beforeText = textToProcess.substring(lastEnd, match.start);
        if (beforeText.trim().isNotEmpty &&
            verseNumber != null &&
            verseText.isNotEmpty) {
          verses.add({
            'type': 'text',
            'text': beforeText,
            'verseNumber': verseNumber,
            'verseText': verseText,
          });
        }
      }

      if (verseNumber != null && verseText.isNotEmpty) {
        verses.add({
          'type': 'verse',
          'verseNumber': verseNumber,
          'verseText': verseText,
        });
      }

      lastEnd = verseEnd;
    }

    if (lastEnd < textToProcess.length) {
      final afterText = textToProcess.substring(lastEnd);
      if (afterText.trim().isNotEmpty) {
        final lastVerse = verses.isNotEmpty && verses.last['type'] == 'verse'
            ? verses.last
            : null;
        if (lastVerse != null) {
          verses.add({
            'type': 'text',
            'text': afterText,
            'verseNumber': lastVerse['verseNumber'],
            'verseText': lastVerse['verseText'],
          });
        } else {
          verses.add({
            'type': 'text',
            'text': afterText,
            'verseNumber': 1,
            'verseText': afterText,
          });
        }
      }
    }

    for (final verseData in verses) {
      if (verseData['type'] == 'verse') {
        final verseNumber = verseData['verseNumber'] as int;
        final verseText = verseData['verseText'] as String;

        final verseKey = 'verse_$verseNumber';
        final verseNumKey = 'verse_${verseNumber}_num';
        final bool isJumpTarget = targetVerse == verseNumber;
        final bool highlightVerse = enableMultiSelect
            ? (multiSelectedVerses?.contains(verseNumber) ?? false)
            : (selectedWordKey == verseKey || selectedWordKey == verseNumKey);

        final GlobalKey? verseAnchorKey = verseKeys == null
            ? null
            : verseKeys.putIfAbsent(verseNumber, () => GlobalKey());
        children.add(
          WidgetSpan(
            alignment: PlaceholderAlignment.middle,
            child: Container(
              key: verseAnchorKey,
              margin: const EdgeInsets.only(right: 4),
              padding: isJumpTarget
                  ? const EdgeInsets.all(5)
                  : EdgeInsets.zero,
              decoration: isJumpTarget
                  ? BoxDecoration(
                      shape: BoxShape.circle,
                      color: _verseTapHighlight,
                      border: Border.all(
                        color: _verseTapHighlight,
                        width: 1.7,
                      ),
                    )
                  : null,
              child: GestureDetector(
                onTap: () {
                  if (enableMultiSelect) {
                    onVerseSelectToggle?.call(verseNumber, verseText);
                  } else {
                    VerseHelper.handleVerseNumberClick(
                      context,
                      bookName,
                      chapterNumber,
                      verseNumber,
                      verseText,
                      onWordClick: onWordClick,
                    );
                  }
                },
                onLongPress: () {
                  if (onVerseAction != null) {
                    onVerseAction(
                      bookName,
                      chapterNumber,
                      verseNumber,
                      verseText,
                      verseNumKey,
                    );
                  } else {
                    VerseHelper.handleVerseNumberClick(
                      context,
                      bookName,
                      chapterNumber,
                      verseNumber,
                      verseText,
                      onWordClick: onWordClick,
                    );
                  }
                },
                child: Text(
                  '$verseNumber',
                  style: baseStyle.copyWith(
                    fontWeight: FontWeight.w400,
                    height: 1,
                    color: isDark ? Colors.grey[400] : Colors.grey[600],
                    backgroundColor: highlightVerse && !isJumpTarget
                        ? _verseTapHighlight
                        : null,
                  ),
                ),
              ),
            ),
          ),
        );
        children.add(const TextSpan(text: ' '));

        if (verseText.isNotEmpty) {
          void addVersePart(String part) {
            final words = part.split(RegExp(r'(\s+)'));
            for (int i = 0; i < words.length; i++) {
              final word = words[i];
              if (word.trim().isEmpty) {
                children.add(
                  TextSpan(
                    text: word,
                    style: baseStyle.copyWith(
                      backgroundColor:
                          highlightVerse ? _verseTapHighlight : null,
                    ),
                  ),
                );
              } else {
                final wordTapRecognizer = TapGestureRecognizer()
                  ..onTap = () {
                    if (enableMultiSelect) {
                      onVerseSelectToggle?.call(verseNumber, verseText);
                    } else {
                      VerseHelper.handleWordClick(
                        context,
                        bookName,
                        chapterNumber,
                        verseNumber,
                        verseText,
                        null,
                        onWordClick: onWordClick,
                      );
                    }
                  };

                final separator =
                    (i < words.length - 1 && words[i + 1].trim().isNotEmpty)
                        ? ' '
                        : '';

                children.add(
                  TextSpan(
                    text: word + separator,
                    style: baseStyle.copyWith(
                      letterSpacing: 0.2,
                      wordSpacing: 1.5,
                      backgroundColor:
                          highlightVerse ? _verseTapHighlight : null,
                    ),
                    recognizer: wordTapRecognizer,
                  ),
                );
              }
            }
          }

          // Для 119 псалма вырезаем заголовки «ԱԼԷՖ», «ԲԷԹ» и т.п. даже если
          // они находятся внутри текста стиха.
          if (bookName == 'Սաղմոս' && chapterNumber == 119) {
            String remaining = verseText;

            while (remaining.isNotEmpty) {
              String? foundHeading;
              int headingIndex = -1;

              for (final h in psalm119Headings) {
                final idx = remaining.indexOf(h);
                if (idx != -1 && (headingIndex == -1 || idx < headingIndex)) {
                  headingIndex = idx;
                  foundHeading = h;
                }
              }

              if (foundHeading == null || headingIndex == -1) {
                addVersePart(remaining);
                break;
              }

              final before = remaining.substring(0, headingIndex).trimRight();
              if (before.isNotEmpty) {
                addVersePart(before);
              }

              // Сам заголовок – крупным чёрным шрифтом по центру.
              children.add(
                WidgetSpan(
                  child: Padding(
                    padding: const EdgeInsets.only(top: 24.0, bottom: 10.0),
                    child: Text(
                      foundHeading,
                      textAlign: TextAlign.center,
                      style: baseStyle.copyWith(
                        fontSize: headingSize,
                        fontWeight: FontWeight.bold,
                        color: isDark ? Colors.white : Colors.black,
                      ),
                    ),
                  ),
                ),
              );

              remaining = remaining
                  .substring(headingIndex + foundHeading.length)
                  .trimLeft();
            }
          } else {
            addVersePart(verseText);
          }
        }
      } else {
        final textContent = verseData['text'] as String;
        final verseNum = verseData['verseNumber'] as int?;
        final verseTxt = verseData['verseText'] as String?;

        // Специальная обработка заголовков акростиха в 118 (119) псалме
        // на основном экране: даже если заголовок «ԱԼԷՖ», «ԲԷԹ» и т.п.
        // слипся с текстом, вырезаем его и рисуем отдельно крупным шрифтом.
        if (bookName == 'Սաղմոս' && chapterNumber == 119) {
          String remaining = textContent;

          while (remaining.isNotEmpty) {
            String? foundHeading;
            int headingIndex = -1;

            for (final h in psalm119Headings) {
              final idx = remaining.indexOf(h);
              if (idx != -1 && (headingIndex == -1 || idx < headingIndex)) {
                headingIndex = idx;
                foundHeading = h;
              }
            }

            if (foundHeading == null || headingIndex == -1) {
              // Никаких заголовков больше нет — весь остаток как обычный текст.
              children.add(
                TextSpan(
                  text: remaining,
                  style: baseStyle,
                ),
              );
              break;
            }

            // Текст до заголовка — обычным стилем.
            final before = remaining.substring(0, headingIndex);
            if (before.trim().isNotEmpty) {
              children.add(
                TextSpan(
                  text: before,
                  style: baseStyle,
                ),
              );
            }

            // Сам заголовок — большим шрифтом по центру.
            children.add(
              WidgetSpan(
                child: Padding(
                  padding: const EdgeInsets.only(top: 24.0, bottom: 10.0),
                  child: Text(
                    foundHeading,
                    textAlign: TextAlign.center,
                    style: baseStyle.copyWith(
                      fontSize: headingSize,
                      fontWeight: FontWeight.bold,
                      color: isDark ? Colors.white : Colors.black,
                    ),
                  ),
                ),
              ),
            );

            // Остаток после заголовка обрабатываем дальше.
            remaining = remaining.substring(headingIndex + foundHeading.length);
          }
        } else if (verseNum != null &&
            verseTxt != null &&
            verseTxt.isNotEmpty) {
          final verseKey = 'verse_$verseNum';
          final verseNumKey = 'verse_${verseNum}_num';
          final bool highlightVerse = enableMultiSelect
              ? (multiSelectedVerses?.contains(verseNum) ?? false)
              : (selectedWordKey == verseKey || selectedWordKey == verseNumKey);

          final words = textContent.split(RegExp(r'(\s+)'));
          for (int i = 0; i < words.length; i++) {
            final word = words[i];
            if (word.trim().isEmpty) {
              children.add(
                TextSpan(
                  text: word,
                  style: baseStyle.copyWith(
                    backgroundColor:
                        highlightVerse ? _verseTapHighlight : null,
                  ),
                ),
              );
            } else {
              final wordTapRecognizer = TapGestureRecognizer()
                ..onTap = () {
                  if (enableMultiSelect) {
                    onVerseSelectToggle?.call(verseNum, verseTxt);
                  } else {
                    VerseHelper.handleWordClick(
                      context,
                      bookName,
                      chapterNumber,
                      verseNum,
                      verseTxt,
                      null,
                      onWordClick: onWordClick,
                    );
                  }
                };

              final separator =
                  (i < words.length - 1 && words[i + 1].trim().isNotEmpty)
                      ? ' '
                      : '';

              children.add(
                TextSpan(
                  text: word + separator,
                  style: baseStyle.copyWith(
                    letterSpacing: 0.2,
                    wordSpacing: 1.5,
                    backgroundColor:
                        highlightVerse ? _verseTapHighlight : null,
                  ),
                  recognizer: wordTapRecognizer,
                ),
              );
            }
          }
        } else {
          children.add(TextSpan(text: textContent, style: baseStyle));
        }
      }
    }

    return SelectableText.rich(TextSpan(style: baseStyle, children: children));
  }

  static Future<void> copyVerse(
    BuildContext context,
    String bookName,
    int chapterNumber,
    int verseNumber,
    String verseText,
  ) async {
    final textToCopy = '$bookName $chapterNumber:$verseNumber\n$verseText';
    await Clipboard.setData(ClipboardData(text: textToCopy));
    if (context.mounted) {
      ScaffoldMessenger.of(context).hideCurrentSnackBar();
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text('Պատճենված է $bookName $chapterNumber:$verseNumber'),
          duration: const Duration(seconds: 1),
        ),
      );
    }
  }

  static Future<void> saveVerse(
    BuildContext context,
    String bookName,
    int chapterNumber,
    int verseNumber,
    String verseText,
  ) async {
    await saveMultipleVerses(context, bookName, chapterNumber, {
      verseNumber: verseText,
    });
  }

  static Future<void> saveMultipleVerses(
    BuildContext context,
    String bookName,
    int chapterNumber,
    Map<int, String> versesToSave, {
    String? verseRange,
  }) async {
    if (versesToSave.isEmpty) return;

    try {
      final prefs = await SharedPreferences.getInstance();
      final savedVerses = prefs.getStringList('saved_verses') ?? [];
      final existingKeys = <String>{};

      for (final savedVerseJson in savedVerses) {
        try {
          final savedVerse = jsonDecode(savedVerseJson) as Map<String, dynamic>;
          final savedBook = savedVerse['book'] as String?;
          final savedChapter = savedVerse['chapter'] as int?;
          final savedVerseNum = savedVerse['verse'] as int?;
          final savedRange = savedVerse['range'] as String?;

          if (savedBook != null && savedChapter != null) {
            if (savedRange != null) {
              existingKeys.add('$savedBook|$savedChapter|$savedRange');
            } else if (savedVerseNum != null) {
              existingKeys.add('$savedBook|$savedChapter|$savedVerseNum');
            }
          }
        } catch (_) {
          continue;
        }
      }

      final entriesToSave = <Map<String, dynamic>>[];
      final now = DateTime.now().toIso8601String();

      if (verseRange != null) {
        // Պահպանել որպես մեկ տիրույթ
        final verseKey = '$bookName|$chapterNumber|$verseRange';
        if (existingKeys.contains(verseKey)) {
          return;
        }
        existingKeys.add(verseKey);

        final allVerseText = versesToSave.entries
            .map((entry) => '${entry.key}. ${entry.value}')
            .join('\n');

        entriesToSave.add({
          'book': bookName,
          'chapter': chapterNumber,
          'verse': verseRange.contains('-')
              ? int.parse(verseRange.split('-')[0])
              : versesToSave.keys.first,
          'range': verseRange,
          'text': allVerseText,
          'date': now,
          'key': verseKey,
          'verseCount': versesToSave.length,
        });
      } else {
        // Պահպանել առանձին համարներ
        versesToSave.forEach((verseNum, verseText) {
          final cleanText = verseText.trim();
          if (cleanText.isEmpty) return;
          final verseKey = '$bookName|$chapterNumber|$verseNum';
          if (existingKeys.contains(verseKey)) {
            return;
          }
          existingKeys.add(verseKey);
          entriesToSave.add({
            'book': bookName,
            'chapter': chapterNumber,
            'verse': verseNum,
            'text': cleanText,
            'date': now,
            'key': verseKey,
            'verseCount': 1,
          });
        });
      }

      if (entriesToSave.isEmpty) {
        if (context.mounted) {
          final count = versesToSave.length;
          final isSingle = count == 1;

          String message;
          if (isSingle) {
            final verseNum = versesToSave.keys.first;
            message = '$bookName $chapterNumber:$verseNum արդեն պահված է';
          } else {
            message = 'Ընտրված հատվածները արդեն պահված են';
          }

          ScaffoldMessenger.of(context).hideCurrentSnackBar();
          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(
              content: Text(message),
              duration: const Duration(seconds: 1),
            ),
          );
        }
        return;
      }

      for (final entry in entriesToSave) {
        savedVerses.add(jsonEncode(entry));
      }
      await prefs.setStringList('saved_verses', savedVerses);

      if (context.mounted) {
        final count = versesToSave.length;
        final isSingle = count == 1;
        final range = entriesToSave.isNotEmpty
            ? entriesToSave.first['range'] as String?
            : null;

        String message;
        if (range != null) {
          message = 'Պահված է $bookName $chapterNumber:$range ($count հատված)';
        } else if (isSingle) {
          // Когда сохраняется один стих, берем номер из versesToSave
          final verseNum = versesToSave.keys.first;
          message = 'Պահված է $bookName $chapterNumber:$verseNum';
        } else {
          // Когда сохраняется несколько стихов, показываем диапазон
          final sortedVerses = versesToSave.keys.toList()..sort();
          final minVerse = sortedVerses.first;
          final maxVerse = sortedVerses.last;
          if (maxVerse - minVerse == sortedVerses.length - 1) {
            // Последовательные стихи
            message =
                'Պահված է $bookName $chapterNumber:$minVerse-$maxVerse ($count հատված)';
          } else {
            // Непоследовательные стихи
            message = 'Պահված են $count հատված';
          }
        }

        ScaffoldMessenger.of(context).hideCurrentSnackBar();
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text(message),
            duration: const Duration(seconds: 1),
          ),
        );
      }
    } catch (e) {
      if (context.mounted) {
        ScaffoldMessenger.of(context).hideCurrentSnackBar();
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text('Սխալ: $e'),
            duration: const Duration(seconds: 1),
          ),
        );
      }
    }
  }

  static void handleWordClick(
    BuildContext context,
    String bookName,
    int chapterNumber,
    int verseNumber,
    String verseText,
    String? wordKey, {
    Function(String, int, int, String, String?)? onWordClick,
  }) {
    if (onWordClick != null) {
      final verseKey = 'verse_$verseNumber';
      onWordClick(bookName, chapterNumber, verseNumber, verseText, verseKey);
    }
  }

  static void handleVerseNumberClick(
    BuildContext context,
    String bookName,
    int chapterNumber,
    int verseNumber,
    String verseText, {
    Function(String, int, int, String, String?)? onWordClick,
  }) {
    if (onWordClick != null) {
      final verseKey = 'verse_${verseNumber}_num';
      onWordClick(bookName, chapterNumber, verseNumber, verseText, verseKey);
    }
  }

  static Future<void> saveCurrentVerse(
    BuildContext context,
    String bookName,
    int chapterNumber,
    int verseNumber,
    String verseText,
  ) async {
    await saveVerse(context, bookName, chapterNumber, verseNumber, verseText);
  }

  static List<SearchResult> searchExactWord(String query) {
    final List<SearchResult> results = [];
    final trimmedQuery = query.trim().toLowerCase();

    bibleText.forEach((book, chapters) {
      chapters.forEach((chapterNum, text) {
        final verses = parseVerses(text);

        verses.forEach((verseNum, verseText) {
          final words = verseText.split(RegExp(r'\s+'));

          for (final word in words) {
            final cleanWord =
                word.replaceAll(RegExp(r'[.,;:!?]'), '').toLowerCase();

            if (cleanWord == trimmedQuery) {
              final startIndex = verseText.indexOf(word);

              final snippetStart = (startIndex - 20).clamp(0, verseText.length);
              final snippetEnd = (startIndex + word.length + 20).clamp(
                0,
                verseText.length,
              );
              final snippet = verseText.substring(snippetStart, snippetEnd);

              results.add(
                SearchResult(
                  book: book,
                  chapter: chapterNum,
                  verse: verseNum,
                  snippet: snippet,
                  startIndex: startIndex - snippetStart,
                  matchedWord: word,
                ),
              );
              break;
            }
          }
        });
      });
    });

    return results;
  }
}

class TransliterationHelper {
  static String normalizeForSearch(String input) {
    // Փոխակերպում ենք գրաբարի ուղղագրությունը աշխարհաբարի
    String normalized = input
        .toLowerCase()
        .replaceAll('ու', 'վ') // գրաբար "ու" -> աշխարհաբար "վ"
        .replaceAll('յ', 'հ') // "յ" -> "հ" (յիշեց -> հիշեց)
        .replaceAll('եա', 'յա') // "եա" -> "յա" (երբեայթ -> երբյաթ)
        .replaceAll('ե', 'ե') // պահպանում ենք (ոչ միշտ փոխվում)
        .replaceAll('ոյ', 'ու') // "ոյ" -> "ու" (աստուածոյ -> աստծու)
        .replaceAll('ու', 'ու') // արդեն ունենք
        .replaceAll('իւ', 'յու') // "իւ" -> "յու" (կիւրի -> կյուրի)
        .replaceAll('ի', 'ի') // պահպանել
        .replaceAll('աւ', 'աւ') // կարող է մնալ "աւ" (բաւական)
        .replaceAll('է', 'ե') // "է" -> "ե" (մէջ -> մեջ)
        .replaceAll('և', 'եւ') // պահպանել
        .replaceAll(RegExp(r'[.,;:!?]'), ''); // հեռացնել կետադրությունը

    // Կարող ես ավելացնել ևս փոխակերպումներ ըստ անհրաժեշտության
    return normalized.trim();
  }

  /// Генерирует триграммы из текста
  static Set<String> generateTrigrams(String text) {
    final Set<String> trigrams = {};
    final normalized = normalizeForSearch(text);

    // Добавляем пробелы в начало и конец для лучшего поиска границ слов
    final padded = ' $normalized ';

    for (int i = 0; i <= padded.length - 3; i++) {
      final trigram = padded.substring(i, i + 3);
      if (trigram.trim().isNotEmpty) {
        trigrams.add(trigram);
      }
    }

    return trigrams;
  }

  /// Вычисляет коэффициент совпадения триграмм (Jaccard similarity)
  static double trigramSimilarity(String query, String text) {
    final queryTrigrams = generateTrigrams(query);
    if (queryTrigrams.isEmpty) return 0.0;

    final textTrigrams = generateTrigrams(text);
    if (textTrigrams.isEmpty) return 0.0;

    // Jaccard similarity: пересечение / объединение
    final intersection = queryTrigrams.intersection(textTrigrams).length;
    final union = queryTrigrams.union(textTrigrams).length;

    if (union == 0) return 0.0;
    return intersection / union;
  }

  static double trigramSimilarityFromSets(
    Set<String> queryTrigrams,
    Set<String> textTrigrams,
  ) {
    if (queryTrigrams.isEmpty || textTrigrams.isEmpty) return 0.0;
    int intersection = 0;
    for (final t in queryTrigrams) {
      if (textTrigrams.contains(t)) intersection++;
    }
    final int union = queryTrigrams.length + textTrigrams.length - intersection;
    if (union == 0) return 0.0;
    return intersection / union;
  }

  // Կարելի է նաև հակառակ փոխակերպումը՝ երբ տեքստում գրաբար ունես
  static String convertClassicalToModern(String text) {
    // Այս ֆունկցիան կարող է օգտագործվել տեքստի համար
    // Բայց որոնման ժամանակ բավարար է normalizeForSearch
    return text
        .toLowerCase()
        .replaceAll('ու', 'վ')
        .replaceAll('յ', 'հ')
        .replaceAll('է', 'ե')
        .replaceAll('ոյ', 'ու');
  }
}

