class ChapterTextScreen extends StatefulWidget {
  final String bookName;
  final int chapterNumber;
  final String text;
  final int? targetVerse;
  final List<int>? initialSelectedVerses;

  const ChapterTextScreen({
    super.key,
    required this.bookName,
    required this.chapterNumber,
    required this.text,
    this.targetVerse,
    this.initialSelectedVerses,
  });

  @override
  State<ChapterTextScreen> createState() => _ChapterTextScreenState();
}

class _ChapterTextScreenState extends State<ChapterTextScreen> {
  OverlayEntry? _overlayEntry;
  String? _selectedVerseInfo;
  int? _selectedVerseNumber;
  String? _selectedVerseText;
  String? _selectedWordKey;
  final Map<int, GlobalKey> _verseKeys = {};
  final ScrollController _scrollController = ScrollController(); // Ավելացրել եմ
  final Map<int, String> _selectedVerses = {};
  double _readerFontSize = _defaultReaderFontSize;
  int? _targetRingVerse;
  Timer? _targetRingTimer;

  @override
  void initState() {
    super.initState();
    _loadReaderFontSize();
    _applyInitialVerseSelection();
    if (widget.initialSelectedVerses == null) {
      _targetRingVerse = widget.targetVerse;
    }
    WidgetsBinding.instance.addPostFrameCallback((_) {
      _scrollToTargetVerse();
    });
  }

  Future<void> _loadReaderFontSize() async {
    final v = await VerseHelper.loadReaderFontSize();
    if (!mounted) return;
    setState(() => _readerFontSize = v);
  }

  Future<void> _showFontSizeSheet() async {
    await VerseHelper.showReaderFontSizeSheet(
      context,
      initial: _readerFontSize,
      onChanged: (v) => setState(() => _readerFontSize = v),
    );
  }

  // Ավելացրել եմ այս մեթոդը
  void _scrollToTargetVerse() {
    if (widget.targetVerse == null) return;
    WidgetsBinding.instance.addPostFrameCallback((_) {
      VerseHelper.scrollToVerse(
        controller: _scrollController,
        keyOf: () => _verseKeys[widget.targetVerse],
        isMounted: () => mounted,
        onDone: _startTargetRingTimeout,
      );
    });
  }

  void _startTargetRingTimeout() {
    if (_targetRingTimer != null || _targetRingVerse == null) return;
    _targetRingTimer = Timer(const Duration(seconds: 3), () {
      if (!mounted) return;
      setState(() => _targetRingVerse = null);
    });
  }

  void _applyInitialVerseSelection() {
    final numbers = widget.initialSelectedVerses;
    if (numbers == null || numbers.isEmpty) return;

    final parsed = VerseHelper.parseVerses(widget.text);
    for (final n in numbers) {
      final verseText = parsed[n];
      if (verseText != null && verseText.isNotEmpty) {
        _selectedVerses[n] = verseText;
      }
    }
  }

  void _toggleVerseSelection(int verseNumber, String verseText) {
    setState(() {
      if (_selectedVerses.containsKey(verseNumber)) {
        _selectedVerses.remove(verseNumber);
      } else {
        _selectedVerses[verseNumber] = verseText;
      }
    });
  }

  // Ավելացնել նոր մեթոդ՝ հարեւան համարները միավորելու համար
  List<Map<String, dynamic>> _getVerseRanges() {
    if (_selectedVerses.isEmpty) return [];

    final sortedVerses = _selectedVerses.keys.toList()..sort();
    final List<Map<String, dynamic>> ranges = [];

    int start = sortedVerses.first;
    int end = sortedVerses.first;

    for (int i = 1; i < sortedVerses.length; i++) {
      if (sortedVerses[i] == end + 1) {
        end = sortedVerses[i];
      } else {
        ranges.add({
          'start': start,
          'end': end,
          'verses': _getVersesInRange(start, end),
        });
        start = sortedVerses[i];
        end = sortedVerses[i];
      }
    }

    ranges.add({
      'start': start,
      'end': end,
      'verses': _getVersesInRange(start, end),
    });

    return ranges;
  }

  // Ավելացնել օժանդակ մեթոդ՝ տիրույթի հատվածները ստանալու համար
  Map<int, String> _getVersesInRange(int start, int end) {
    final Map<int, String> versesInRange = {};
    for (int i = start; i <= end; i++) {
      if (_selectedVerses.containsKey(i)) {
        versesInRange[i] = _selectedVerses[i]!;
      }
    }
    return versesInRange;
  }

  void _clearSelections() {
    setState(() {
      _selectedVerses.clear();
    });
  }

  Future<void> _saveSelectedVerses() async {
    if (_selectedVerses.isEmpty) return;

    final verseRanges = _getVerseRanges();

    // Отдельно собираем одиночные стихи и диапазоны
    final Map<int, String> singleVerses = {};
    final List<Map<String, dynamic>> multiVerseRanges = [];

    for (final range in verseRanges) {
      final start = range['start'] as int;
      final end = range['end'] as int;
      final verses = range['verses'] as Map<int, String>;

      if (start == end) {
        // Одиночный стих – собираем их в один общий вызов
        singleVerses.addAll(verses);
      } else {
        // Диапазон – сохраняем отдельно с verseRange
        multiVerseRanges.add({'start': start, 'end': end, 'verses': verses});
      }
    }

    // Сначала сохраняем диапазоны
    for (final range in multiVerseRanges) {
      final start = range['start'] as int;
      final end = range['end'] as int;
      final verses = range['verses'] as Map<int, String>;

      await VerseHelper.saveMultipleVerses(
        context,
        widget.bookName,
        widget.chapterNumber,
        verses,
        verseRange: '$start-$end',
      );
    }

    // Потом одним вызовом сохраняем все одиночные стихи, чтобы сообщение
    // показывало общее количество, а не по одному разу
    if (singleVerses.isNotEmpty) {
      await VerseHelper.saveMultipleVerses(
        context,
        widget.bookName,
        widget.chapterNumber,
        singleVerses,
      );
    }

    if (!mounted) return;
    setState(() {
      _selectedVerses.clear();
    });
  }

  void _openChapter(int chapterNumber) {
    final text =
        bibleText[widget.bookName]?[chapterNumber] ?? 'Տեքստը դեռ չի ավելացվել';
    Navigator.pushReplacement(
      context,
      MaterialPageRoute(
        builder: (_) => ChapterTextScreen(
          bookName: widget.bookName,
          chapterNumber: chapterNumber,
          text: text,
        ),
      ),
    );
  }

  Widget _buildNavigationControls(
    bool isDark,
    bool hasPreviousChapter,
    bool hasNextChapter,
  ) {
    return Row(
      mainAxisAlignment: MainAxisAlignment.spaceBetween,
      crossAxisAlignment: CrossAxisAlignment.center,
      children: [
        GestureDetector(
          onTap: hasPreviousChapter
              ? () => _openChapter(widget.chapterNumber - 1)
              : null,
          child: Container(
            width: 44,
            height: 44,
            margin: const EdgeInsets.symmetric(horizontal: 10),
            alignment: Alignment.center,
            decoration: BoxDecoration(
              shape: BoxShape.circle,
              color: hasPreviousChapter ? Colors.grey[800] : Colors.grey[700],
              boxShadow: [
                BoxShadow(
                  color: Colors.black.withOpacity(0.1),
                  blurRadius: 4,
                  offset: const Offset(0, 2),
                ),
              ],
            ),
            child: const Padding(
              padding: EdgeInsets.only(right: 2),
              child: Icon(
                Icons.arrow_back_ios_new,
                size: 18,
                color: Colors.white,
              ),
            ),
          ),
        ),
        Container(
          height: 44,
          padding: const EdgeInsets.symmetric(horizontal: 16),
          alignment: Alignment.center,
          decoration: BoxDecoration(
            color: isDark
                ? const Color.fromARGB(255, 19, 19, 19)
                : Colors.grey[350],
            borderRadius: BorderRadius.circular(22),
          ),
          child: Text(
            '${widget.chapterNumber}',
            textAlign: TextAlign.center,
            style: TextStyle(
              fontSize: 16,
              fontWeight: FontWeight.w500,
              height: 1.0,
              color: isDark ? Colors.white : const Color.fromARGB(255, 0, 0, 0),
            ),
          ),
        ),
        GestureDetector(
          onTap: hasNextChapter
              ? () => _openChapter(widget.chapterNumber + 1)
              : null,
          child: Container(
            width: 44,
            height: 44,
            margin: const EdgeInsets.symmetric(horizontal: 10),
            alignment: Alignment.center,
            decoration: BoxDecoration(
              shape: BoxShape.circle,
              color: hasNextChapter ? Colors.grey[800] : Colors.grey[700],
              boxShadow: [
                BoxShadow(
                  color: const Color.fromARGB(255, 19, 19, 19).withOpacity(0.1),
                  blurRadius: 4,
                  offset: const Offset(0, 2),
                ),
              ],
            ),
            child: const Padding(
              padding: EdgeInsets.only(left: 2),
              child: Icon(
                Icons.arrow_forward_ios,
                size: 18,
                color: Colors.white,
              ),
            ),
          ),
        ),
      ],
    );
  }

  Widget _buildMultiSelectControls(bool isDark) {
    return Padding(
      padding: const EdgeInsets.symmetric(horizontal: 12),
      child: Row(
        children: [
          Expanded(
            child: Text(
              'Ընտրված՝ ${_selectedVerses.length}',
              style: TextStyle(
                fontSize: 16,
                fontWeight: FontWeight.w600,
                color: isDark ? Colors.white : Colors.black,
              ),
            ),
          ),
          TextButton(
            onPressed: _clearSelections,
            child: const Text('Չեղարկել'),
          ),
          const SizedBox(width: 8),
          ElevatedButton(
            onPressed: _selectedVerses.isEmpty ? null : _saveSelectedVerses,
            child: const Text('Պահել'),
          ),
        ],
      ),
    );
  }

  void _showActionPanel(
    String bookName,
    int chapterNumber,
    int verseNumber,
    String verseText,
    String? wordKey,
  ) {
    if (wordKey != null && wordKey.endsWith('_num')) {
      if (_selectedWordKey == wordKey) {
        _hideActionPanel();
        return;
      }

      _hideActionPanel();

      setState(() {
        _selectedVerseInfo = '$bookName $chapterNumber:$verseNumber';
        _selectedVerseNumber = verseNumber;
        _selectedVerseText = verseText;
        _selectedWordKey = wordKey;
      });

      WidgetsBinding.instance.addPostFrameCallback((_) {
        final key = _verseKeys[verseNumber];
        double topPosition = MediaQuery.of(context).padding.top + 60;

        if (key?.currentContext != null) {
          final RenderBox? renderBox =
              key!.currentContext!.findRenderObject() as RenderBox?;
          if (renderBox != null) {
            final position = renderBox.localToGlobal(Offset.zero);
            topPosition = position.dy - 50;
            if (topPosition < MediaQuery.of(context).padding.top + 60) {
              topPosition = MediaQuery.of(context).padding.top + 60;
            }
          }
        }

        final overlay = Overlay.of(context);
        _overlayEntry = OverlayEntry(
          builder: (context) => Positioned(
            top: topPosition,
            left: 16,
            right: 16,
            child: Material(
              elevation: 8,
              borderRadius: BorderRadius.circular(12),
              color: Theme.of(context).scaffoldBackgroundColor,
              child: Container(
                padding: const EdgeInsets.symmetric(
                  horizontal: 12,
                  vertical: 8,
                ),
                decoration: BoxDecoration(
                  borderRadius: BorderRadius.circular(12),
                  border: Border.all(
                    color: Colors.grey.withValues(alpha: 0.3),
                    width: 1,
                  ),
                ),
                child: Row(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    Text(
                      _selectedVerseInfo ?? '',
                      style: Theme.of(context).textTheme.bodySmall?.copyWith(
                            fontWeight: FontWeight.bold,
                            color: Colors.grey,
                          ),
                    ),
                    const SizedBox(width: 12),
                    IconButton(
                      icon: const Icon(Icons.content_copy, size: 20),
                      onPressed: () {
                        VerseHelper.copyVerse(
                          context,
                          widget.bookName,
                          widget.chapterNumber,
                          _selectedVerseNumber!,
                          _selectedVerseText!,
                        );
                        _hideActionPanel();
                      },
                      tooltip: 'Պատճենել',
                      padding: EdgeInsets.zero,
                      constraints: const BoxConstraints(),
                    ),
                    const SizedBox(width: 4),
                    IconButton(
                      icon: const Icon(Icons.bookmark_add, size: 20),
                      onPressed: () async {
                        if (_selectedVerseNumber == null ||
                            _selectedVerseText == null) {
                          return;
                        }
                        final versesToSave = Map<int, String>.from(
                          _selectedVerses,
                        );
                        versesToSave[_selectedVerseNumber!] =
                            _selectedVerseText!;
                        await VerseHelper.saveMultipleVerses(
                          context,
                          widget.bookName,
                          widget.chapterNumber,
                          versesToSave,
                        );
                        if (!mounted) return;
                        setState(() {
                          _selectedVerses.clear();
                        });
                        _hideActionPanel();
                      },
                      tooltip: 'Պահել',
                      padding: EdgeInsets.zero,
                      constraints: const BoxConstraints(),
                      color: Colors.grey,
                    ),
                    const SizedBox(width: 4),
                    IconButton(
                      icon: const Icon(Icons.close, size: 18),
                      onPressed: _hideActionPanel,
                      tooltip: 'Փակել',
                      padding: EdgeInsets.zero,
                      constraints: const BoxConstraints(),
                    ),
                  ],
                ),
              ),
            ),
          ),
        );
        overlay.insert(_overlayEntry!);
      });
    } else {
      final bool isSameSelection = _selectedWordKey == wordKey;
      _hideActionPanel();
      setState(() {
        _selectedWordKey = isSameSelection ? null : wordKey;
      });
    }
  }

  void _hideActionPanel({bool fromDispose = false}) {
    try {
      if (_overlayEntry != null) {
        _overlayEntry!.remove();
        _overlayEntry = null;
      }
    } catch (_) {}

    if (!fromDispose && mounted) {
      setState(() {
        _selectedVerseInfo = null;
        _selectedVerseNumber = null;
        _selectedVerseText = null;
        _selectedWordKey = null;
      });
    }
  }

  @override
  void dispose() {
    _targetRingTimer?.cancel();
    _hideActionPanel(fromDispose: true);
    _scrollController.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final bool isDark = Theme.of(context).brightness == Brightness.dark;
    final int totalChapters = chapterCounts[widget.bookName] ?? 1;
    final bool hasPreviousChapter = widget.chapterNumber > 1;
    final bool hasNextChapter = widget.chapterNumber < totalChapters;

    return Scaffold(
      appBar: AppBar(
        title: Container(
          width: double.infinity,
          padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),
          decoration: BoxDecoration(
            color: isDark
                ? const Color.fromARGB(255, 19, 19, 19)
                : Colors.grey[350],
            borderRadius: BorderRadius.circular(20),
          ),
          child: FittedBox(
            fit: BoxFit.scaleDown,
            child: Text(
              widget.bookName,
              maxLines: 1,
              style: TextStyle(
                fontSize: 16,
                fontWeight: FontWeight.w500,
                color: isDark
                    ? const Color.fromARGB(255, 255, 255, 255)
                    : const Color.fromARGB(255, 0, 0, 0),
              ),
            ),
          ),
        ),
        centerTitle: true,
        leading: IconButton(
          icon: const Icon(Icons.close, color: Colors.white),
          onPressed: () {
            ScaffoldMessenger.of(context).hideCurrentSnackBar();
            Navigator.pop(context);
          },
        ),
        actions: [
          IconButton(
            icon: const Icon(Icons.format_size),
            tooltip: 'Տառերի չափ',
            onPressed: _showFontSizeSheet,
          ),
          if (_selectedVerses.isNotEmpty)
            IconButton(
              icon: const Icon(Icons.bookmark_add),
              tooltip: 'Պահել ընտրվածները',
              onPressed: _saveSelectedVerses,
            )
          else
            Builder(
              builder: (context) {
                final versePattern = RegExp(r'(\d+)[*]?\s*');
                final firstMatch = versePattern.firstMatch(widget.text);
                if (firstMatch != null) {
                  final verseNum = int.tryParse(firstMatch.group(1) ?? '');
                  if (verseNum != null) {
                    final allMatches =
                        versePattern.allMatches(widget.text).toList();
                    final nextMatch =
                        allMatches.length > 1 ? allMatches[1] : null;
                    final verseEnd = nextMatch?.start ?? widget.text.length;
                    final verseText =
                        widget.text.substring(firstMatch.end, verseEnd).trim();

                    if (verseText.isNotEmpty) {
                      return IconButton(
                        icon: const Icon(Icons.bookmark_add),
                        onPressed: () {
                          VerseHelper.saveCurrentVerse(
                            context,
                            widget.bookName,
                            widget.chapterNumber,
                            verseNum,
                            verseText,
                          );
                        },
                        tooltip: 'Պահել հատված',
                      );
                    }
                  }
                }
                return const SizedBox(width: 48);
              },
            ),
        ],
      ),
      body: GestureDetector(
        onTap: () {
          _hideActionPanel();
        },
        behavior: HitTestBehavior.translucent,
        child: Column(
          children: [
            Expanded(
              child: Padding(
                padding: const EdgeInsets.all(16.0),
                child: SingleChildScrollView(
                  controller: _scrollController, // Ավելացրել եմ
                  child: VerseHelper.buildClickableVerseText(
                    context,
                    widget.text,
                    widget.bookName,
                    widget.chapterNumber,
                    readerFontSize: _readerFontSize,
                    selectedWordKey: _selectedWordKey,
                    verseKeys: _verseKeys,
                    targetVerse: _targetRingVerse,
                    onWordClick: (
                      bookName,
                      chapterNumber,
                      verseNumber,
                      verseText,
                      wordKey,
                    ) {
                      _showActionPanel(
                        bookName,
                        chapterNumber,
                        verseNumber,
                        verseText,
                        wordKey,
                      );
                    },
                    enableMultiSelect: true,
                    multiSelectedVerses: _selectedVerses.keys.toSet(),
                    onVerseSelectToggle: (verseNumber, verseText) {
                      _toggleVerseSelection(verseNumber, verseText);
                    },
                    onVerseAction: (
                      bookName,
                      chapterNumber,
                      verseNumber,
                      verseText,
                      wordKey,
                    ) {
                      _showActionPanel(
                        bookName,
                        chapterNumber,
                        verseNumber,
                        verseText,
                        wordKey,
                      );
                    },
                  ),
                ),
              ),
            ),
            Container(
              height: 100,
              alignment: Alignment.center,
              decoration: BoxDecoration(
                color: isDark
                    ? const Color.fromARGB(255, 0, 0, 0)
                    : Colors.grey[100],
                border: Border(
                  top: BorderSide(
                    color: isDark ? Colors.grey[800]! : Colors.grey[300]!,
                    width: 1,
                  ),
                ),
              ),
              child: _buildNavigationControls(
                isDark,
                hasPreviousChapter,
                hasNextChapter,
              ),
            ),
          ],
        ),
      ),
    );
  }
}

class SearchResult {
  final String book;
  final int chapter;
  final int verse;
  final String snippet;
  final int startIndex;
  final String matchedWord; // Ավելացնել ճշգրիտ համընկնած բառը

  SearchResult({
    required this.book,
    required this.chapter,
    required this.verse,
    required this.snippet,
    required this.startIndex,
    required this.matchedWord, // Ավելացնել ճշգրիտ համընկնած բառը
  });
}

class IndexedVerse {
  final String book;
  final int chapter;
  final int verse;
  final String original;
  final String normalized;
  final Set<String> trigrams;

  IndexedVerse({
    required this.book,
    required this.chapter,
    required this.verse,
    required this.original,
    required this.normalized,
    required this.trigrams,
  });
}

class SearchScreen extends StatefulWidget {
  const SearchScreen({super.key});

  @override
  State<SearchScreen> createState() => _SearchScreenState();
}

class _SearchScreenState extends State<SearchScreen> {
  final TextEditingController _controller = TextEditingController();

  final List<SearchResult> _results = [];
  final List<IndexedVerse> _index = [];

  Timer? _debounce;

  @override
  void initState() {
    super.initState();
    _buildIndex();
  }

  /// 🔹 ՄԵԿ ԱՆԳԱՄ կառուցում ենք search index
  void _buildIndex() {
    bibleText.forEach((book, chapters) {
      chapters.forEach((chapterNum, text) {
        final verses = VerseHelper.parseVerses(text);

        verses.forEach((verseNum, verseText) {
          if (verseText.trim().isEmpty) return;

          final normalized =
              TransliterationHelper.normalizeForSearch(verseText);
          final trigrams = TransliterationHelper.generateTrigrams(verseText);

          _index.add(
            IndexedVerse(
              book: book,
              chapter: chapterNum,
              verse: verseNum,
              original: verseText,
              normalized: normalized,
              trigrams: trigrams,
            ),
          );
        });
      });
    });
  }

  /// 🔹 Debounced search
  void _onSearchChanged(String text) {
    _debounce?.cancel();
    _debounce = Timer(const Duration(milliseconds: 500), () => _search(text));
  }

  /// 🔹 Արագ search с триграммами
  void _search(String query) {
    final trimmed = query.trim();
    if (trimmed.isEmpty) {
      setState(() => _results.clear());
      return;
    }

    final normalizedQuery = TransliterationHelper.normalizeForSearch(trimmed);
    final queryTrigrams = TransliterationHelper.generateTrigrams(trimmed);

    final temp = <SearchResult>[];
    final Map<SearchResult, double> scores = {};
    const maxResults = 100;
    const minSimilarity = 0.3; // Минимальный порог совпадения триграмм

    for (final v in _index) {
      if (temp.length >= maxResults) break;
      final textNorm = v.normalized;

      // Сначала проверяем точное совпадение (приоритет)
      int idx = textNorm.indexOf(normalizedQuery);
      bool exactMatch = false;

      if (idx != -1) {
        // Требуем точное совпадение СЛОВА (границы слова = пробел/перенос строки/начало/конец)
        final bool isWordStart =
            idx == 0 || textNorm[idx - 1] == ' ' || textNorm[idx - 1] == '\n';
        final int afterIndex = idx + normalizedQuery.length;
        final bool isWordEnd = afterIndex >= textNorm.length ||
            textNorm[afterIndex] == ' ' ||
            textNorm[afterIndex] == '\n';

        if (isWordStart && isWordEnd) {
          exactMatch = true;
        }
      }

      // Если нет точного совпадения, используем триграммы
      double similarity = 0.0;
      if (!exactMatch && queryTrigrams.length >= 3) {
        similarity = TransliterationHelper.trigramSimilarityFromSets(
          queryTrigrams,
          v.trigrams,
        );
        if (similarity < minSimilarity) continue;
      } else if (!exactMatch) {
        continue;
      }

      // Находим позицию совпадения для сниппета
      if (idx == -1) {
        // Если использовали триграммы, ищем лучшее совпадение
        idx = textNorm.indexOf(normalizedQuery);
        if (idx == -1) {
          // Берем начало текста если не нашли
          idx = 0;
        }
      }

      final start = (idx - 30).clamp(0, v.original.length);
      final end = (idx + normalizedQuery.length + 30).clamp(
        0,
        v.original.length,
      );

      final result = SearchResult(
        book: v.book,
        chapter: v.chapter,
        verse: v.verse,
        snippet: v.original.substring(start, end),
        startIndex: idx - start,
        matchedWord: trimmed,
      );

      // Приоритет точным совпадениям
      scores[result] = exactMatch ? 1.0 : similarity;
      temp.add(result);
    }

    // Сортируем по релевантности (точные совпадения первыми)
    temp.sort((a, b) {
      final scoreA = scores[a] ?? 0.0;
      final scoreB = scores[b] ?? 0.0;
      return scoreB.compareTo(scoreA);
    });

    // Ограничиваем количество результатов
    final finalResults = temp.take(maxResults).toList();

    setState(() {
      _results
        ..clear()
        ..addAll(finalResults);
    });
  }

  @override
  void dispose() {
    _debounce?.cancel();
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('Փնտրել'),
        leading: IconButton(
          icon: const Icon(Icons.arrow_back),
          onPressed: () => Navigator.pop(context),
        ),
      ),
      body: Column(
        children: [
          Padding(
            padding: const EdgeInsets.all(16),
            child: Container(
              height: 50,
              padding: const EdgeInsets.symmetric(horizontal: 16),
              decoration: BoxDecoration(
                color: Theme.of(context).brightness == Brightness.dark
                    ? Colors.grey[700]
                    : Colors.grey[100],
                borderRadius: BorderRadius.circular(25),
              ),
              child: Center(
                child: TextField(
                  controller: _controller,
                  style: TextStyle(
                    color: Theme.of(context).brightness == Brightness.dark
                        ? Colors.white
                        : Colors.black,
                  ),
                  decoration: InputDecoration(
                    hintText: 'Փնտրել բառ կամ արտահայտություն...',
                    hintStyle: const TextStyle(
                      color: Colors.black,
                    ),
                    border: InputBorder.none,
                    prefixIcon: Icon(
                      Icons.search,
                      color: Theme.of(context).brightness == Brightness.dark
                          ? Colors.grey[400]
                          : Colors.grey[600],
                    ),
                  ),
                  onChanged: _onSearchChanged,
                ),
              ),
            ),
          ),
          Expanded(
            child: _results.isEmpty && _controller.text.isNotEmpty
                ? const Center(child: Text('Ոչինչ չի գտնվել'))
                : ListView.builder(
                    itemCount: _results.length,
                    itemBuilder: (context, index) {
                      final r = _results[index];

                      // Надёжно находим совпадение уже в оригинальном сниппете,
                      // чтобы подсветка всегда была на правильном слове.
                      final snippetLower = r.snippet.toLowerCase();
                      final wordLower = r.matchedWord.toLowerCase();
                      final idxInSnippet = snippetLower.indexOf(wordLower);

                      String before;
                      String match;
                      String after;

                      if (idxInSnippet == -1) {
                        // На всякий случай: если не нашли, показываем без подсветки
                        before = r.snippet;
                        match = '';
                        after = '';
                      } else {
                        before = r.snippet.substring(0, idxInSnippet);
                        match = r.snippet.substring(
                          idxInSnippet,
                          idxInSnippet + r.matchedWord.length,
                        );
                        after = r.snippet.substring(
                          idxInSnippet + r.matchedWord.length,
                        );
                      }

                      return Card(
                        margin: const EdgeInsets.symmetric(
                          horizontal: 12,
                          vertical: 6,
                        ),
                        child: ListTile(
                          title: Text(
                            '${r.book} ${r.chapter}.${r.verse}',
                            style: const TextStyle(fontWeight: FontWeight.bold),
                          ),
                          subtitle: RichText(
                            text: TextSpan(
                              style: TextStyle(
                                color: Theme.of(context).brightness ==
                                        Brightness.dark
                                    ? Colors.white
                                    : Colors.black,
                              ),
                              children: [
                                TextSpan(
                                  text: '...$before',
                                  style: TextStyle(color: Colors.grey[600]),
                                ),
                                TextSpan(
                                  text: match,
                                  style: const TextStyle(
                                    color: Colors.blue,
                                    fontWeight: FontWeight.bold,
                                  ),
                                ),
                                TextSpan(
                                  text: '$after...',
                                  style: TextStyle(color: Colors.grey[600]),
                                ),
                              ],
                            ),
                          ),
                          onTap: () {
                            Navigator.push(
                              context,
                              MaterialPageRoute(
                                builder: (_) => ChapterTextScreenWithHighlight(
                                  bookName: r.book,
                                  chapterNumber: r.chapter,
                                  searchQuery: _controller.text.trim(),
                                  targetVerse: r.verse,
                                  targetWord: _controller.text.contains(' ')
                                      ? null
                                      : r.matchedWord,
                                ),
                              ),
                            );
                          },
                        ),
                      );
                    },
                  ),
          ),
        ],
      ),
    );
  }
}

class ChapterTextScreenWithHighlight extends StatefulWidget {
  final String bookName;
  final int chapterNumber;
  final String searchQuery;
  final int? targetVerse;
  final String? targetWord; // Ավելացնել նպատակային բառը

  const ChapterTextScreenWithHighlight({
    super.key,
    required this.bookName,
    required this.chapterNumber,
    required this.searchQuery,
    this.targetVerse,
    this.targetWord, // Ավելացնել նպատակային բառը
  });

  @override
  State<ChapterTextScreenWithHighlight> createState() =>
      _ChapterTextScreenWithHighlightState();
}

class _ChapterTextScreenWithHighlightState
    extends State<ChapterTextScreenWithHighlight> {
  final ScrollController _scrollController = ScrollController();
  OverlayEntry? _overlayEntry;
  String? _selectedVerseInfo;
  int? _selectedVerseNumber;
  String? _selectedVerseText;
  String? _selectedWordKey;
  final Map<int, GlobalKey> _verseKeys = {};
  final Map<int, String> _selectedVerses = {};
  double _readerFontSize = _defaultReaderFontSize;

  @override
  void initState() {
    super.initState();
    _loadReaderFontSize();
    WidgetsBinding.instance.addPostFrameCallback((_) {
      _scrollToTargetVerse();
    });
  }

  Future<void> _loadReaderFontSize() async {
    final v = await VerseHelper.loadReaderFontSize();
    if (!mounted) return;
    setState(() => _readerFontSize = v);
  }

  Future<void> _showFontSizeSheet() async {
    await VerseHelper.showReaderFontSizeSheet(
      context,
      initial: _readerFontSize,
      onChanged: (v) => setState(() => _readerFontSize = v),
    );
  }

  void _toggleVerseSelection(int verseNumber, String verseText) {
    setState(() {
      if (_selectedVerses.containsKey(verseNumber)) {
        _selectedVerses.remove(verseNumber);
      } else {
        _selectedVerses[verseNumber] = verseText;
      }
    });
  }

  List<Map<String, dynamic>> _getVerseRanges() {
    if (_selectedVerses.isEmpty) return [];

    final sortedVerses = _selectedVerses.keys.toList()..sort();
    final List<Map<String, dynamic>> ranges = [];

    int start = sortedVerses.first;
    int end = sortedVerses.first;

    for (int i = 1; i < sortedVerses.length; i++) {
      if (sortedVerses[i] == end + 1) {
        end = sortedVerses[i];
      } else {
        ranges.add({
          'start': start,
          'end': end,
          'verses': _getVersesInRange(start, end),
        });
        start = sortedVerses[i];
        end = sortedVerses[i];
      }
    }

    ranges.add({
      'start': start,
      'end': end,
      'verses': _getVersesInRange(start, end),
    });

    return ranges;
  }

  Map<int, String> _getVersesInRange(int start, int end) {
    final Map<int, String> versesInRange = {};
    for (int i = start; i <= end; i++) {
      if (_selectedVerses.containsKey(i)) {
        versesInRange[i] = _selectedVerses[i]!;
      }
    }
    return versesInRange;
  }

  void _clearSelections() {
    setState(() {
      _selectedVerses.clear();
    });
  }

  Future<void> _saveSelectedVerses() async {
    if (_selectedVerses.isEmpty) return;

    final verseRanges = _getVerseRanges();

    // Отдельно собираем одиночные стихи и диапазоны
    final Map<int, String> singleVerses = {};
    final List<Map<String, dynamic>> multiVerseRanges = [];

    for (final range in verseRanges) {
      final start = range['start'] as int;
      final end = range['end'] as int;
      final verses = range['verses'] as Map<int, String>;

      if (start == end) {
        // Одиночный стих – собираем их в один общий вызов
        singleVerses.addAll(verses);
      } else {
        // Диапазон – сохраняем отдельно с verseRange
        multiVerseRanges.add({'start': start, 'end': end, 'verses': verses});
      }
    }

    // Сначала сохраняем диапазоны
    for (final range in multiVerseRanges) {
      final start = range['start'] as int;
      final end = range['end'] as int;
      final verses = range['verses'] as Map<int, String>;

      await VerseHelper.saveMultipleVerses(
        context,
        widget.bookName,
        widget.chapterNumber,
        verses,
        verseRange: '$start-$end',
      );
    }

    // Потом одним вызовом сохраняем все одиночные стихи, чтобы сообщение
    // показывало общее количество, а не по одному разу
    if (singleVerses.isNotEmpty) {
      await VerseHelper.saveMultipleVerses(
        context,
        widget.bookName,
        widget.chapterNumber,
        singleVerses,
      );
    }

    if (!mounted) return;
    setState(() {
      _selectedVerses.clear();
    });
  }

  Widget _buildMultiSelectControls(bool isDark) {
    return Padding(
      padding: const EdgeInsets.symmetric(horizontal: 12),
      child: Row(
        children: [
          Expanded(
            child: Text(
              'Ընտրված՝ ${_selectedVerses.length}',
              style: TextStyle(
                fontSize: 16,
                fontWeight: FontWeight.w600,
                color: isDark ? Colors.white : Colors.black,
              ),
            ),
          ),
          TextButton(
            onPressed: _clearSelections,
            child: const Text('Չեղարկել'),
          ),
          const SizedBox(width: 8),
          ElevatedButton(
            onPressed: _selectedVerses.isEmpty ? null : _saveSelectedVerses,
            child: const Text('Պահել'),
          ),
        ],
      ),
    );
  }

  @override
  void dispose() {
    _hideActionPanel(fromDispose: true);
    _scrollController.dispose();
    super.dispose();
  }

  void _scrollToTargetVerse() {
    if (widget.targetVerse == null) return;
    WidgetsBinding.instance.addPostFrameCallback((_) {
      VerseHelper.scrollToVerse(
        controller: _scrollController,
        keyOf: () => _verseKeys[widget.targetVerse],
        isMounted: () => mounted,
      );
    });
  }

  void _showActionPanel(
    String bookName,
    int chapterNumber,
    int verseNumber,
    String verseText,
    String? wordKey,
  ) {
    if (wordKey != null && wordKey.endsWith('_num')) {
      if (_selectedWordKey == wordKey) {
        _hideActionPanel();
        return;
      }

      _hideActionPanel();

      setState(() {
        _selectedVerseInfo = '$bookName $chapterNumber:$verseNumber';
        _selectedVerseNumber = verseNumber;
        _selectedVerseText = verseText;
        _selectedWordKey = wordKey;
      });

      WidgetsBinding.instance.addPostFrameCallback((_) {
        final key = _verseKeys[verseNumber];
        double topPosition = MediaQuery.of(context).padding.top + 60;

        if (key?.currentContext != null) {
          final RenderBox? renderBox =
              key!.currentContext!.findRenderObject() as RenderBox?;
          if (renderBox != null) {
            final position = renderBox.localToGlobal(Offset.zero);
            topPosition = position.dy - 50;
            if (topPosition < MediaQuery.of(context).padding.top + 60) {
              topPosition = MediaQuery.of(context).padding.top + 60;
            }
          }
        }

        final overlay = Overlay.of(context);
        _overlayEntry = OverlayEntry(
          builder: (context) => Positioned(
            top: topPosition,
            left: 16,
            right: 16,
            child: Material(
              elevation: 8,
              borderRadius: BorderRadius.circular(12),
              color: Theme.of(context).scaffoldBackgroundColor,
              child: Container(
                padding: const EdgeInsets.symmetric(
                  horizontal: 12,
                  vertical: 8,
                ),
                decoration: BoxDecoration(
                  borderRadius: BorderRadius.circular(12),
                  border: Border.all(
                    color: Colors.grey.withValues(alpha: 0.3),
                    width: 1,
                  ),
                ),
                child: Row(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    Text(
                      _selectedVerseInfo ?? '',
                      style: Theme.of(context).textTheme.bodySmall?.copyWith(
                            fontWeight: FontWeight.bold,
                            color: Colors.grey,
                          ),
                    ),
                    const SizedBox(width: 12),
                    IconButton(
                      icon: const Icon(Icons.content_copy, size: 20),
                      onPressed: () {
                        VerseHelper.copyVerse(
                          context,
                          widget.bookName,
                          widget.chapterNumber,
                          _selectedVerseNumber!,
                          _selectedVerseText!,
                        );
                        _hideActionPanel();
                      },
                      tooltip: 'Պատճենել',
                      padding: EdgeInsets.zero,
                      constraints: const BoxConstraints(),
                    ),
                    const SizedBox(width: 4),
                    IconButton(
                      icon: const Icon(Icons.bookmark_add, size: 20),
                      onPressed: () {
                        VerseHelper.saveVerse(
                          context,
                          widget.bookName,
                          widget.chapterNumber,
                          _selectedVerseNumber!,
                          _selectedVerseText!,
                        );
                        _hideActionPanel();
                      },
                      tooltip: 'Պահել',
                      padding: EdgeInsets.zero,
                      constraints: const BoxConstraints(),
                      color: Colors.grey,
                    ),
                    const SizedBox(width: 4),
                    IconButton(
                      icon: const Icon(Icons.close, size: 18),
                      onPressed: _hideActionPanel,
                      tooltip: 'Փակել',
                      padding: EdgeInsets.zero,
                      constraints: const BoxConstraints(),
                    ),
                  ],
                ),
              ),
            ),
          ),
        );
        overlay.insert(_overlayEntry!);
      });
    } else {
      final bool isSameSelection = _selectedWordKey == wordKey;
      _hideActionPanel();
      setState(() {
        _selectedWordKey = isSameSelection ? null : wordKey;
      });
    }
  }

  void _hideActionPanel({bool fromDispose = false}) {
    _overlayEntry?.remove();
    _overlayEntry = null;

    if (!fromDispose && mounted) {
      setState(() {
        _selectedVerseInfo = null;
        _selectedVerseNumber = null;
        _selectedVerseText = null;
        _selectedWordKey = null;
      });
    }
  }

